command:
$HistoryLength=0;root=Directory[];
Print["READ_ACCEPTED_PAIR_MEASUREMENTS"];
PrependTo[$Path,"/u/home/r/rushil/.Mathematica/Applications"];
$FeynCalcStartupMessages=False;Get["FeynCalc`"];
relative="Hgq/s08_pair_mapping_result/s08_result.wl";
path=FileNameJoin[{root,relative}];proof=Get[path];
receipt=Import[FileNameJoin[{root,"Hgq/s08_pair_mapping_result/s08_execution.json"}],"RawJSON"];
checks=<|"accepted proof receipt"->TrueQ[receipt["passed"]],
"same accepted result"->(receipt["result_sha256"][relative]===IntegerString[FileHash[path,"SHA256"],16,64]),
"expected proof schema"->(proof["Schema"]==="polarized-sidis-pair-mapping-comparison-v1"&&proof["Channel"]==="Hgq"),
"accepted recorded checks"->TrueQ[And@@Values[proof["Checks"]]],
"same executed proof source"->(proof["SourceHash"]===FileHash[FileNameJoin[{root,"common/s08_check_gluon_pair_mapping.wls"}],"SHA256"])|>;
If[!And@@Values[checks],Print["FAIL: accepted pair measurement binding"];Quit[1]];
rows=Map[Function[component,Join[KeyTake[component,{"Kind","Index","ComponentIndex","ExtractionSeconds","MergeSeconds"}],
<|"PairCount"->Length[component["PairEvidence"]],"TotalPairSeconds"->Total[Lookup[component["PairEvidence"],"Seconds"]],
"LargestPairSeconds"->Max[Lookup[component["PairEvidence"],"Seconds"]],
"LargestPairInputBytes"->Max[Lookup[component["PairEvidence"],"InputBytes"]],
"TotalPairOutputBytes"->Total[Lookup[component["PairEvidence"],"OutputBytes"]]|>]],proof["Components"]];
AssociateTo[checks,"numeric recorded timings"->And@@Flatten[Table[NumericQ[row[key]],{row,rows},{key,{"ExtractionSeconds","MergeSeconds","TotalPairSeconds","LargestPairSeconds"}}]]];
If[!And@@Values[checks],Print["FAIL: recorded measurement schema"];Quit[1]];
report=<|"checks"->checks,"measurements"->rows,"original_execution"->KeyTake[receipt,{"job_id","node","wall_seconds","peak_observed_tree_rss_bytes","child_maxrss_bytes"}],
"input_sha256"->IntegerString[FileHash[path,"SHA256"],16,64],"physics_recomputed"->False,"finite_nlo_fhats_computed"->False,"job_id"->Environment["JOB_ID"]|>;
Export[FileNameJoin[{root,"Hgq/s08_pair_mapping_result/s08_measurements.json"}],report,"RawJSON"];
Print["PASS: s08_pair_measurements"];Quit[0];
